1	/****************************************************************************
2	 * app/dsi_probe/dsi_probe_main.c
3	 *
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * Staged MIPI-DSI validation for the ESP32-P4X Function EV Board.
7	 * The optional video command creates an EK79007-owned DPI panel, submits one
8	 * RGB565 colour-bar frame through draw_bitmap() and deliberately does not
9	 * start LVGL.
10	 ****************************************************************************/
11	
12	/****************************************************************************
13	 * Included Files
14	 ****************************************************************************/
15	
16	#include <nuttx/config.h>
17	
18	#include <errno.h>
19	#include <stdbool.h>
20	#include <stdio.h>
21	#include <stdlib.h>
22	#include <string.h>
23	
24	#include <nuttx/signal.h>
25	#include <nuttx/video/mipi_display.h>
26	#include <nuttx/video/mipi_dsi.h>
27	
28	#include <arch/board/board.h>
29	#include <arch/chip/esp_mipi_dsi_dpi_panel.h>
30	
31	#include "ek79007.h"
32	
33	/****************************************************************************
34	 * Pre-processor Definitions
35	 ****************************************************************************/
36	
37	#define DSI_PROBE_LANES        2
38	#define DSI_PROBE_HS_RATE_HZ   1000000000
39	#define DSI_PROBE_LP_RATE_HZ   10000000
40	
41	#define DSI_PROBE_VIDEO_SECONDS_DEFAULT 30
42	#define DSI_PROBE_VIDEO_SECONDS_MAX    600
43	
44	/****************************************************************************
45	 * Private Data
46	 ****************************************************************************/
47	
48	/* The panel driver owns the EK79007 DCS sequence.  The probe only supplies
49	 * the P4X link parameters and calls the panel lifecycle in production order.
50	 */
51	
52	static const struct ek79007_panel_config_s g_dsi_probe_panel_config =
53	{
54	  .timing     = NULL,
55	  .init_cmds  = NULL,
56	  .ninit_cmds = 0,
57	  .mode_flags = MIPI_DSI_MODE_LPM,
58	  .hs_rate    = DSI_PROBE_HS_RATE_HZ,
59	  .lp_rate    = DSI_PROBE_LP_RATE_HZ,
60	  .lanes      = DSI_PROBE_LANES,
61	  .format     = MIPI_DSI_FMT_RGB565,
62	};
