68	/****************************************************************************
69	 * Name: dsi_probe_fail
70	 ****************************************************************************/
71	
72	static int dsi_probe_fail(FAR const char *step, int ret)
73	{
74	  printf("dsi_probe: FAIL step=%s ret=%d (%s)\n", step, ret,
75	         strerror(-ret));
76	  return EXIT_FAILURE;
77	}
