79	static int dsi_probe_parse_video_request(int argc, FAR char *argv[],
80	                                         FAR unsigned int *seconds)
81	{
82	  FAR char *endptr;
83	  unsigned long value;
84	
85	  *seconds = DSI_PROBE_VIDEO_SECONDS_DEFAULT;
86	  if (argc == 1)
87	    {
88	      return OK;
89	    }
90	
91	  if (strcmp(argv[1], "video") != 0 || argc > 3)
92	    {
93	      return -EINVAL;
94	    }
95	
96	  if (argc == 3)
97	    {
98	      value = strtoul(argv[2], &endptr, 10);
99	      if (*argv[2] == '\0' || *endptr != '\0' || value == 0 ||
100	          value > DSI_PROBE_VIDEO_SECONDS_MAX)
101	        {
102	          return -EINVAL;
103	        }
104	
105	      *seconds = (unsigned int)value;
106	    }
107	
108	  return 1;
109	}
