113	/****************************************************************************
114	 * Name: dsi_probe_panel_shutdown
115	 ****************************************************************************/
116	
117	static int dsi_probe_panel_shutdown(FAR struct ek79007_panel_s *panel)
118	{
119	  int display_ret;
120	  int ret;
121	
122	  ret = board_mipi_dsi_backlight_set(false);
123	  display_ret = ek79007_panel_shutdown(panel);
124	  return ret < 0 ? ret : display_ret;
125	}
