161	/****************************************************************************
162	 * Name: dsi_probe_run_video_pattern
163	 ****************************************************************************/
164	
165	static int dsi_probe_run_video_pattern(FAR struct mipi_dsi_host *host,
166	                                       FAR struct ek79007_panel_s *panel,
167	                                       unsigned int seconds)
168	{
169	  FAR struct esp_mipi_dsi_dpi_panel_s *dpi_panel;
170	  FAR void *frame_buffer;
171	  size_t frame_buffer_bytes;
172	  unsigned int elapsed;
173	  int display_ret;
174	  int status_ret;
175	  int ret;
176	
177	  dpi_panel = panel->dpi_panel;
178	  if (dpi_panel == NULL)
179	    {
180	      return -EPIPE;
181	    }
182	
183	  ret = esp_mipi_dsi_dpi_panel_get_frame_buffer(
184	    dpi_panel, &frame_buffer, &frame_buffer_bytes);
185	  if (ret < 0)
186	    {
187	      return ret;
188	    }
189	
190	  /* The known-good ESP-IDF sample enables brightness before its first
191	   * draw_bitmap().  Preserve that order for this one-to-one P4X experiment.
192	   */
193	
194	  ret = board_mipi_dsi_backlight_set(true);
195	  if (ret < 0)
196	    {
197	      return ret;
198	    }
199	
200	  dsi_probe_fill_rgb565_colour_bars(frame_buffer,
201	                                    dpi_panel->config.hactive,
202	                                    dpi_panel->config.vactive);
203	
204	  ret = ek79007_panel_draw_bitmap(panel, frame_buffer, frame_buffer_bytes);
205	  if (ret < 0)
206	    {
207	      board_mipi_dsi_backlight_set(false);
208	      return ret;
209	    }
210	
211	  printf("dsi_probe: EK79007 DPI RGB565 vertical colour bars active for "
212	         "%u seconds; "
213	         "LVGL is not involved\n", seconds);
214	  printf("dsi_probe: draw_bitmap() submitted; visually confirm colour bars "
215	         "before recording a display PASS\n");
216	  status_ret = board_mipi_dsi_video_dump_status(host, "probe-start");
217	  if (status_ret < 0)
218	    {
219	      printf("dsi_probe: DMA status snapshot unavailable ret=%d\n",
220	             status_ret);
221	    }
222	
223	  for (elapsed = 0; elapsed < seconds; elapsed++)
224	    {
225	      ret = nxsig_usleep(1000 * 1000);
226	      if (ret < 0)
227	        {
228	          break;
229	        }
230	
231	      if (elapsed == 0)
232	        {
233	          status_ret = board_mipi_dsi_video_dump_status(host,
234	                                                         "probe-after-1s");
235	          if (status_ret < 0)
236	            {
237	              printf("dsi_probe: DMA status snapshot unavailable ret=%d\n",
238	                     status_ret);
239	            }
240	        }
241	    }
242	
243	  status_ret = board_mipi_dsi_video_dump_status(host, "probe-before-stop");
244	  if (status_ret < 0)
245	    {
246	      printf("dsi_probe: DMA status snapshot unavailable ret=%d\n",
247	             status_ret);
248	    }
249	
250	  display_ret = dsi_probe_panel_shutdown(panel);
251	  if (display_ret < 0 && ret == OK)
252	    {
253	      ret = display_ret;
254	    }
255	
256	  return ret;
257	}
258	
259	#endif /* CONFIG_LVX_USE_DEMO_CONTEST2026_031_DSI_PROBE_VIDEO_PATTERN */
