261	/****************************************************************************
262	 * Public Functions
263	 ****************************************************************************/
264	
265	/****************************************************************************
266	 * Name: main
267	 ****************************************************************************/
268	
269	int main(int argc, FAR char *argv[])
270	{
271	  struct mipi_dsi_host *host;
272	  struct mipi_dsi_device device;
273	  struct ek79007_panel_s panel;
274	  struct ek79007_panel_config_s panel_config;
275	  struct esp_mipi_dsi_dpi_panel_s dpi_panel;
276	  uint8_t short_payload = 0;
277	  uint8_t long_payload[] =
278	  {
279	    0, 0, 0
280	  };
281	
282	  uint8_t power_mode;
283	  unsigned int video_seconds;
284	  bool dcs_read_available;
285	  bool video_requested;
286	  ssize_t transferred;
287	  int ret;
288	
289	  ret = dsi_probe_parse_video_request(argc, argv, &video_seconds);
290	  if (ret < 0)
291	    {
292	      printf("usage: dsi_probe [video [seconds]]\n");
293	      return EXIT_FAILURE;
294	    }
295	
296	  video_requested = ret > 0;
297	
298	  printf("=== ESP32-P4X MIPI-DSI Host probe ===\n");
299	  printf("link: 2 lanes, 1000 Mbps; panel: EK79007; video: %s\n",
300	         video_requested ? "DMA colour-bar request" : "disabled");
301	
302	  ret = board_mipi_dsi_initialize(&host);
303	  if (ret < 0)
304	    {
305	      return dsi_probe_fail("host_initialize", ret);
306	    }
307	
308	  printf("dsi_probe: host bus=%d initialized\n", host->bus);
309	
310	  memset(&device, 0, sizeof(device));
311	  memset(&panel, 0, sizeof(panel));
312	  memset(&dpi_panel, 0, sizeof(dpi_panel));
313	  panel_config = g_dsi_probe_panel_config;
314	
315	  if (video_requested)
316	    {
317	#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_031_DSI_PROBE_VIDEO_PATTERN
318	      panel_config.dpi_panel = &dpi_panel;
319	      panel_config.dpi_config = board_mipi_dsi_dpi_panel_config_get();
320	#else
321	      printf("dsi_probe: video command is disabled; enable "
322	             "CONFIG_LVX_USE_DEMO_CONTEST2026_031_"
323	             "DSI_PROBE_VIDEO_PATTERN\n");
324	      board_mipi_dsi_shutdown(host);
325	      return EXIT_FAILURE;
326	#endif
327	    }
328	
329	  device.host = host;
330	  device.channel = 0;
331	  snprintf(device.name, sizeof(device.name), "ek79007-probe");
332	
333	  ret = ek79007_panel_setup(&panel, &device, &panel_config);
334	  if (ret < 0)
335	    {
336	      board_mipi_dsi_shutdown(host);
337	      return dsi_probe_fail("ek79007_panel_setup", ret);
338	    }
339	
340	  ret = mipi_dsi_attach(&device);
341	  if (ret < 0)
342	    {
343	      ek79007_panel_shutdown(&panel);
344	      board_mipi_dsi_shutdown(host);
345	      return dsi_probe_fail("device_attach", ret);
346	    }
347	
348	  /* The hardware reset belongs after the panel object and DBI path exist,
349	   * matching esp_lcd_panel_reset() in the ESP-IDF EK79007 lifecycle.
350	   */
351	
352	  ret = board_mipi_dsi_panel_reset();
353	  if (ret < 0)
354	    {
355	      ek79007_panel_shutdown(&panel);
356	      mipi_dsi_detach(&device);
357	      board_mipi_dsi_shutdown(host);
358	      return dsi_probe_fail("panel_hardware_reset", ret);
359	    }
360	
361	  /* Generic packets are intentionally kept for the command-only Host test.
362	   * The video test omits them so its panel path matches the ESP-IDF colour
363	   * bar example without non-panel DSI traffic before initialisation.
364	   */
365	
366	  if (!video_requested)
367	    {
368	      transferred = mipi_dsi_generic_write(&device, &short_payload,
369	                                           sizeof(short_payload));
370	      if (transferred < 0)
371	        {
372	          ek79007_panel_shutdown(&panel);
373	          mipi_dsi_detach(&device);
374	          board_mipi_dsi_shutdown(host);
375	          return dsi_probe_fail("generic_short_write", (int)transferred);
376	        }
377	
378	      printf("dsi_probe: generic short packet accepted\n");
379	
380	      transferred = mipi_dsi_generic_write(&device, long_payload,
381	                                           sizeof(long_payload));
382	      if (transferred < 0)
383	        {
384	          ek79007_panel_shutdown(&panel);
385	          mipi_dsi_detach(&device);
386	          board_mipi_dsi_shutdown(host);
387	          return dsi_probe_fail("generic_long_write", (int)transferred);
388	        }
389	
390	      printf("dsi_probe: generic long packet accepted\n");
391	    }
392	
393	  ret = ek79007_panel_initialize(&panel);
394	  if (ret < 0)
395	    {
396	      ek79007_panel_shutdown(&panel);
397	      mipi_dsi_detach(&device);
398	      board_mipi_dsi_shutdown(host);
399	      return dsi_probe_fail("ek79007_panel_initialize", ret);
400	    }
401	
402	  printf("dsi_probe: EK79007 panel driver initialisation accepted\n");
403	
404	  if (video_requested)
405	    {
406	      /* The ESP-IDF EK79007 component intentionally reports the standard
407	       * DCS display_on/off operation as unsupported.  The validated sample
408	       * therefore starts DPI and draws without sending DCS 0x29.
409	       */
410	
411	      printf("dsi_probe: strict ESP-IDF video profile: skip DCS display "
412	             "on (0x29)\n");
413	    }
414	  else
415	    {
416	      ret = ek79007_panel_set_display(&panel, true);
417	      if (ret < 0)
418	        {
419	          ek79007_panel_shutdown(&panel);
420	          mipi_dsi_detach(&device);
421	          board_mipi_dsi_shutdown(host);
422	          return dsi_probe_fail("panel_display_on", ret);
423	        }
424	
425	      printf("dsi_probe: EK79007 display enabled\n");
426	    }
427	
428	  if (video_requested)
429	    {
430	      dcs_read_available = false;
431	      printf("dsi_probe: skip DCS power-mode read while DPI video is "
432	             "active\n");
433	    }
434	  else
435	    {
436	      power_mode = 0;
437	      ret = mipi_dsi_dcs_get_power_mode(&device, &power_mode);
438	      if (ret < 0)
439	        {
440	          dcs_read_available = false;
441	          printf("dsi_probe: DCS power-mode read unavailable ret=%d (%s); "
442	                 "continuing because this panel may be write-only in M1\n",
443	                 ret, strerror(-ret));
444	        }
445	      else
446	        {
447	          dcs_read_available = true;
448	          printf("dsi_probe: DCS power mode=0x%02x\n", power_mode);
449	        }
450	    }
451	
452	  if (video_requested)
453	    {
454	#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_031_DSI_PROBE_VIDEO_PATTERN
455	      ret = dsi_probe_run_video_pattern(host, &panel, video_seconds);
456	      if (ret < 0)
457	        {
458	          ek79007_panel_shutdown(&panel);
459	          mipi_dsi_detach(&device);
460	          board_mipi_dsi_shutdown(host);
461	          return dsi_probe_fail("video_dma_scanout", ret);
462	        }
463	#else
464	      ek79007_panel_shutdown(&panel);
465	      mipi_dsi_detach(&device);
466	      board_mipi_dsi_shutdown(host);
467	      return EXIT_FAILURE;
468	#endif
469	    }
470	
471	  ret = mipi_dsi_detach(&device);
472	  if (ret < 0)
473	    {
474	      board_mipi_dsi_shutdown(host);
475	      return dsi_probe_fail("device_detach", ret);
476	    }
477	
478	  ret = board_mipi_dsi_shutdown(host);
479	  if (ret < 0)
480	    {
481	      return dsi_probe_fail("host_shutdown", ret);
482	    }
483	
484	  if (video_requested)
485	    {
486	      printf("dsi_probe: HOST PASS DPI DMA sequence completed; visual "
487	             "display result pending (DCS read=skipped in video mode)\n");
488	    }
489	  else
490	    {
491	      printf("dsi_probe: PASS command Host validation completed "
492	             "(DCS read=%s)\n",
493	             dcs_read_available ? "available" : "unavailable");
494	    }
495	
496	  return EXIT_SUCCESS;
497	}
