1	/****************************************************************************
2	 * drivers/lcd/ek79007.c
3	 *
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * EK79007 MIPI-DSI panel controller driver.
7	 *
8	 * The EK79007 receives DCS and vendor commands through the generic NuttX
9	 * MIPI-DSI framework.  A caller may attach a P4 DPI panel object at setup;
10	 * initialization then follows the ESP-IDF order: DCS setup first, continuous
11	 * DPI scanout second.
12	 ****************************************************************************/
13	
14	/****************************************************************************
15	 * Included Files
16	 ****************************************************************************/
17	
18	#include <nuttx/config.h>
19	
20	#include <errno.h>
21	
22	#include <nuttx/signal.h>
23	#include <nuttx/video/mipi_display.h>
24	
25	#include <arch/chip/esp_mipi_dsi_dpi_panel.h>
26	
27	#include "ek79007.h"
28	
29	/****************************************************************************
30	 * Pre-processor Definitions
31	 ****************************************************************************/
32	
33	#define EK79007_RESET_DELAY_US       (20 * 1000)
34	#define EK79007_SLEEP_EXIT_DELAY_US  (120 * 1000)
35	#define EK79007_SLEEP_ENTER_DELAY_US (120 * 1000)
36	
37	/****************************************************************************
38	 * Private Data
39	 ****************************************************************************/
40	
41	/* The controller vendor sequence is intentionally small.  Panel suppliers
42	 * may require a different sequence, supplied in config->init_cmds.  The
43	 * default comes from the EK79007 reference implementation and is limited to
44	 * controller-level setup; display timing remains a DSI host responsibility.
45	 */
46	
47	static const uint8_t g_ek79007_cmd_80[] =
48	{
49	  0x8b
50	};
51	
52	static const uint8_t g_ek79007_cmd_81[] =
53	{
54	  0x78
55	};
56	
57	static const uint8_t g_ek79007_cmd_82[] =
58	{
59	  0x84
60	};
61	
62	static const uint8_t g_ek79007_cmd_83[] =
63	{
64	  0x88
65	};
66	
67	static const uint8_t g_ek79007_cmd_84[] =
68	{
69	  0xa8
70	};
71	
72	static const uint8_t g_ek79007_cmd_85[] =
73	{
74	  0xe3
75	};
76	
77	static const uint8_t g_ek79007_cmd_86[] =
78	{
79	  0x88
80	};
81	
82	static const struct ek79007_init_cmd_s g_ek79007_default_init_cmds[] =
83	{
84	  {0x80, g_ek79007_cmd_80, sizeof(g_ek79007_cmd_80), 0},
85	  {0x81, g_ek79007_cmd_81, sizeof(g_ek79007_cmd_81), 0},
86	  {0x82, g_ek79007_cmd_82, sizeof(g_ek79007_cmd_82), 0},
87	  {0x83, g_ek79007_cmd_83, sizeof(g_ek79007_cmd_83), 0},
88	  {0x84, g_ek79007_cmd_84, sizeof(g_ek79007_cmd_84), 0},
89	  {0x85, g_ek79007_cmd_85, sizeof(g_ek79007_cmd_85), 0},
90	  {0x86, g_ek79007_cmd_86, sizeof(g_ek79007_cmd_86), 0},
91	};
