280	/****************************************************************************
281	 * Name: ek79007_panel_initialize
282	 ****************************************************************************/
283	
284	int ek79007_panel_initialize(FAR struct ek79007_panel_s *panel)
285	{
286	  FAR const struct ek79007_init_cmd_s *cmds;
287	  size_t ncmds;
288	  uint8_t lanes;
289	  int ret;
290	
291	  ret = ek79007_check_panel(panel);
292	  if (ret < 0)
293	    {
294	      return ret;
295	    }
296	
297	  if (panel->initialized)
298	    {
299	      return panel->sleeping ? -EBUSY : OK;
300	    }
301	
302	  cmds = panel->config->init_cmds;
303	  ncmds = panel->config->ninit_cmds;
304	  if (cmds == NULL)
305	    {
306	      /* Keep the default path byte-for-byte ordered like the EK79007
307	       * ESP-IDF component used to validate the P4X board:
308	       *
309	       *   0x80 .. 0x86 -> 0xb2 -> 0x11 -> 120 ms.
310	       *
311	       * In particular, moving PAD_CONTROL behind the vendor registers is
312	       * intentional.  A custom sequence retains the historical contract
313	       * below: PAD_CONTROL is emitted before caller-provided commands.
314	       */
315	
316	      cmds = g_ek79007_default_init_cmds;
317	      ncmds = sizeof(g_ek79007_default_init_cmds) /
318	              sizeof(g_ek79007_default_init_cmds[0]);
319	
320	      ret = ek79007_send_sequence(panel, cmds, ncmds);
321	      if (ret < 0)
322	        {
323	          return ret;
324	        }
325	
326	      lanes = panel->config->lanes == 2 ? EK79007_DCS_PAD_2_LANES :
327	                                          EK79007_DCS_PAD_4_LANES;
328	      ret = ek79007_write(panel, EK79007_DCS_PAD_CONTROL, &lanes,
329	                          sizeof(lanes));
330	      if (ret < 0)
331	        {
332	          return ret;
333	        }
334	
335	      ret = ek79007_write(panel, MIPI_DCS_EXIT_SLEEP_MODE, NULL, 0);
336	      if (ret < 0)
337	        {
338	          return ret;
339	        }
340	
341	      ret = ek79007_delay(120);
342	      if (ret < 0)
343	        {
344	          return ret;
345	        }
346	    }
347	  else
348	    {
349	      if (ncmds == 0)
350	        {
351	          return -EINVAL;
352	        }
353	
354	      lanes = panel->config->lanes == 2 ? EK79007_DCS_PAD_2_LANES :
355	                                          EK79007_DCS_PAD_4_LANES;
356	      ret = ek79007_write(panel, EK79007_DCS_PAD_CONTROL, &lanes,
357	                          sizeof(lanes));
358	      if (ret < 0)
359	        {
360	          return ret;
361	        }
362	
363	      ret = ek79007_send_sequence(panel, cmds, ncmds);
364	      if (ret < 0)
365	        {
366	          return ret;
367	        }
368	    }
369	
370	  if (panel->dpi_panel != NULL)
371	    {
372	#ifdef CONFIG_ESPRESSIF_MIPI_DSI_DPI_PANEL
373	      ret = esp_mipi_dsi_dpi_panel_initialize(panel->dpi_panel);
374	      if (ret < 0)
375	        {
376	          return ret;
377	        }
378	#else
379	      return -ENOTSUP;
380	#endif
381	    }
382	
383	  panel->initialized = true;
384	  panel->display_on = false;
385	  panel->sleeping = false;
386	  return OK;
387	}
