496	/****************************************************************************
497	 * Name: ek79007_panel_set_sleep
498	 ****************************************************************************/
499	
500	int ek79007_panel_set_sleep(FAR struct ek79007_panel_s *panel, bool sleep)
501	{
502	  int ret;
503	
504	  ret = ek79007_check_panel(panel);
505	  if (ret < 0)
506	    {
507	      return ret;
508	    }
509	
510	  if (!panel->initialized)
511	    {
512	      return -EPIPE;
513	    }
514	
515	  if (panel->sleeping == sleep)
516	    {
517	      return OK;
518	    }
519	
520	  if (sleep)
521	    {
522	      ret = ek79007_panel_set_display(panel, false);
523	      if (ret < 0)
524	        {
525	          return ret;
526	        }
527	
528	      ret = mipi_dsi_dcs_enter_sleep_mode(panel->dsi);
529	      if (ret < 0)
530	        {
531	          return ret;
532	        }
533	
534	      ret = nxsig_usleep(EK79007_SLEEP_ENTER_DELAY_US);
535	      if (ret < 0)
536	        {
537	          return ret;
538	        }
539	
540	      panel->sleeping = true;
541	      return OK;
542	    }
543	
544	  ret = mipi_dsi_dcs_exit_sleep_mode(panel->dsi);
545	  if (ret < 0)
546	    {
547	      return ret;
548	    }
549	
550	  ret = nxsig_usleep(EK79007_SLEEP_EXIT_DELAY_US);
551	  if (ret < 0)
552	    {
553	      return ret;
554	    }
555	
556	  panel->sleeping = false;
557	  return OK;
558	}
