26	/****************************************************************************
27	 * Name: esp_mipi_dsi_dpi_panel_bytes_per_pixel
28	 ****************************************************************************/
29	
30	static int esp_mipi_dsi_dpi_panel_bytes_per_pixel(
31	  enum esp_mipi_dsi_dpi_color_format_e format, FAR size_t *bytes_per_pixel)
32	{
33	  if (bytes_per_pixel == NULL)
34	    {
35	      return -EINVAL;
36	    }
37	
38	  switch (format)
39	    {
40	      case ESP_MIPI_DSI_DPI_COLOR_RGB565:
41	        *bytes_per_pixel = 2;
42	        return OK;
43	
44	      case ESP_MIPI_DSI_DPI_COLOR_RGB888:
45	        *bytes_per_pixel = 3;
46	        return OK;
47	
48	      default:
49	        return -EINVAL;
50	    }
51	}
