53	/****************************************************************************
54	 * Name: esp_mipi_dsi_dpi_panel_validate
55	 ****************************************************************************/
56	
57	static int esp_mipi_dsi_dpi_panel_validate(
58	  FAR const struct esp_mipi_dsi_dpi_panel_config_s *config,
59	  FAR size_t *frame_buffer_bytes)
60	{
61	  size_t bytes_per_pixel;
62	  int ret;
63	
64	  if (config == NULL || frame_buffer_bytes == NULL ||
65	      config->channel > 3 || config->hactive == 0 ||
66	      config->vactive == 0 || config->pixel_clock_hz == 0 ||
67	      config->input_format != config->output_format)
68	    {
69	      return -EINVAL;
70	    }
71	
72	  ret = esp_mipi_dsi_dpi_panel_bytes_per_pixel(config->input_format,
73	                                                &bytes_per_pixel);
74	  if (ret < 0)
75	    {
76	      return ret;
77	    }
78	
79	  if (config->hactive > SIZE_MAX / config->vactive ||
80	      (size_t)config->hactive * config->vactive >
81	        SIZE_MAX / bytes_per_pixel)
82	    {
83	      return -EOVERFLOW;
84	    }
85	
86	  *frame_buffer_bytes = (size_t)config->hactive * config->vactive *
87	                        bytes_per_pixel;
88	  return OK;
89	}
