126	/****************************************************************************
127	 * Name: esp_mipi_dsi_dpi_panel_initialize
128	 ****************************************************************************/
129	
130	int esp_mipi_dsi_dpi_panel_initialize(
131	  FAR struct esp_mipi_dsi_dpi_panel_s *panel)
132	{
133	  struct esp_mipi_dsi_video_dma_config_s config;
134	  FAR void *frame_buffer;
135	  int ret;
136	
137	  if (panel == NULL || !panel->created || panel->host == NULL)
138	    {
139	      return -EINVAL;
140	    }
141	
142	  if (panel->initialized)
143	    {
144	      return OK;
145	    }
146	
147	  ret = esp_mipi_dsi_dma_buffer_allocate(panel->frame_buffer_bytes,
148	                                         &frame_buffer);
149	  if (ret < 0)
150	    {
151	      return ret;
152	    }
153	
154	  memset(&config, 0, sizeof(config));
155	  config.channel = panel->config.channel;
156	  config.hactive = panel->config.hactive;
157	  config.hsync = panel->config.hsync;
158	  config.hback_porch = panel->config.hback_porch;
159	  config.hfront_porch = panel->config.hfront_porch;
160	  config.vactive = panel->config.vactive;
161	  config.vsync = panel->config.vsync;
162	  config.vback_porch = panel->config.vback_porch;
163	  config.vfront_porch = panel->config.vfront_porch;
164	  config.pixel_clock_hz = panel->config.pixel_clock_hz;
165	  config.hsync_active_low = panel->config.hsync_active_low;
166	  config.vsync_active_low = panel->config.vsync_active_low;
167	  config.input_format = panel->config.input_format;
168	  config.output_format = panel->config.output_format;
169	  config.frame_buffer = frame_buffer;
170	  config.frame_buffer_bytes = panel->frame_buffer_bytes;
171	
172	  ret = esp_mipi_dsi_dma_buffer_sync_for_device(
173	    frame_buffer, panel->frame_buffer_bytes);
174	  if (ret < 0)
175	    {
176	      esp_mipi_dsi_dma_buffer_free(frame_buffer);
177	      return ret;
178	    }
179	
180	  ret = esp_mipi_dsi_video_dma_start(panel->host, &config);
181	  if (ret < 0)
182	    {
183	      esp_mipi_dsi_dma_buffer_free(frame_buffer);
184	      return ret;
185	    }
186	
187	  panel->frame_buffer = frame_buffer;
188	  panel->initialized = true;
189	  return OK;
190	}
