270	void esp_mipi_dsi_dpi_panel_destroy(
271	  FAR struct esp_mipi_dsi_dpi_panel_s *panel)
272	{
273	  int ret;
274	
275	  if (panel == NULL)
276	    {
277	      return;
278	    }
279	
280	  if (panel->initialized)
281	    {
282	      ret = esp_mipi_dsi_dpi_panel_stop(panel);
283	      if (ret < 0)
