1287	  syslog(LOG_INFO,
1288	         "INFO: MIPI-DSI DMA events stage=%s enable=%08" PRIx32
1289	         " status=%08" PRIx32 " done=%08" PRIx32 " errors=%08" PRIx32
1290	         " channel_cfg0=%08" PRIx32 " channel_cfg1=%08" PRIx32 "\n",
1291	         stage, dma_dev->ch[ESP_MIPI_DSI_DMA_CHANNEL].int_st_ena0.val,
1292	         channel_status, channel_status & ESP_MIPI_DSI_DMA_DONE_EVENTS,
1293	         channel_status & ESP_MIPI_DSI_DMA_ERROR_EVENTS,
1294	         dma_dev->ch[ESP_MIPI_DSI_DMA_CHANNEL].cfg0.val,
1295	         dma_dev->ch[ESP_MIPI_DSI_DMA_CHANNEL].cfg1.val);
1296	  syslog(LOG_INFO,
1297	         "INFO: MIPI-DSI Bridge events stage=%s raw=%08" PRIx32
1298	         " enable=%08" PRIx32 " status=%08" PRIx32
1299	         " underrun_raw=%d underrun_status=%d underrun_count=%" PRIu32
1300	         " first_underrun=%d\n",
1301	         stage, bridge_raw, bridge->int_ena.val, bridge_status,
1302	         (bridge_raw & MIPI_DSI_BRG_LL_EVENT_UNDERRUN) != 0,
1303	         (bridge_status & MIPI_DSI_BRG_LL_EVENT_UNDERRUN) != 0,
