1336	static bool esp_mipi_dsi_message_is_read(uint8_t type)
1337	{
1338	  /* A DSI data type, rather than incidental receive-buffer fields, defines
1339	   * whether the Host must start BTA and wait for an RX payload.  In
1340	   * particular, DCS write helpers only require transmit fields to be set.
1341	   */
1342	
1343	  switch (type)
1344	    {
1345	      case MIPI_DSI_GENERIC_READ_0_PARAM:
1346	      case MIPI_DSI_GENERIC_READ_1_PARAM:
1347	      case MIPI_DSI_GENERIC_READ_2_PARAM:
1348	      case MIPI_DSI_DCS_READ_0_PARAM:
1349	        return true;
1350	
1351	      default:
1352	        return false;
1353	    }
1354	}
