1356	static int esp_mipi_dsi_attach(FAR struct mipi_dsi_host *host,
1357	                               FAR struct mipi_dsi_device *device)
1358	{
1359	  FAR struct esp_mipi_dsi_s *priv = &g_esp_mipi_dsi;
1360	  int ret;
1361	
1362	  if (host != &priv->host || device == NULL || device->channel > 3 ||
1363	      device->lanes == 0 || device->lanes > ESP_MIPI_DSI_MAX_DATA_LANES)
1364	    {
1365	      return -EINVAL;
1366	    }
1367	
1368	  ret = nxmutex_lock(&priv->lock);
1369	  if (ret < 0)
1370	    {
1371	      return ret;
1372	    }
1373	
1374	  ret = priv->ready ? OK : -ESHUTDOWN;
1375	  nxmutex_unlock(&priv->lock);
1376	  return ret;
1377	}
1378	
1379	static int esp_mipi_dsi_detach(FAR struct mipi_dsi_host *host,
1380	                               FAR struct mipi_dsi_device *device)
1381	{
1382	  if (host != &g_esp_mipi_dsi.host || device == NULL)
1383	    {
1384	      return -EINVAL;
1385	    }
1386	
1387	  return OK;
1388	}
1389	
1390	static ssize_t esp_mipi_dsi_transfer(FAR struct mipi_dsi_host *host,
1391	                                     FAR const struct mipi_dsi_msg *msg)
1392	{
1393	  FAR struct esp_mipi_dsi_s *priv = &g_esp_mipi_dsi;
1394	  struct mipi_dsi_packet packet;
1395	  bool is_read;
1396	  ssize_t ret;
1397	
1398	  if (host != &priv->host || msg == NULL || msg->channel > 3 ||
1399	      (msg->tx_len > 0 && msg->tx_buf == NULL))
1400	    {
1401	      return -EINVAL;
1402	    }
1403	
1404	  is_read = esp_mipi_dsi_message_is_read(msg->type);
1405	  if (is_read && (msg->rx_len == 0 || msg->rx_buf == NULL))
1406	    {
1407	      return -EINVAL;
1408	    }
1409	
1410	  ret = mipi_dsi_create_packet(&packet, msg);
1411	  if (ret < 0)
1412	    {
1413	      return ret;
1414	    }
1415	
1416	  if (!mipi_dsi_packet_format_is_short(msg->type) &&
1417	      !mipi_dsi_packet_format_is_long(msg->type))
1418	    {
1419	      return -ENOTSUP;
1420	    }
1421	
1422	  ret = nxmutex_lock(&priv->lock);
1423	  if (ret < 0)
1424	    {
1425	      return ret;
1426	    }
1427	
1428	  if (!priv->ready)
1429	    {
1430	      ret = -ESHUTDOWN;
1431	    }
1432	  else if (is_read)
1433	    {
1434	      ret = esp_mipi_dsi_read_packet(priv, &packet, msg);
1435	    }
1436	  else
1437	    {
1438	      ret = esp_mipi_dsi_write_packet(priv, &packet, msg->channel,
1439	                                      msg->type);
1440	      if (ret == OK)
1441	        {
1442	          ret = msg->tx_len;
1443	        }
1444	    }
1445	
1446	  nxmutex_unlock(&priv->lock);
1447	  return ret;
1448	}
