1450	/****************************************************************************
1451	 * Public Functions
1452	 ****************************************************************************/
1453	
1454	int esp_mipi_dsi_host_initialize(
1455	  FAR const struct esp_mipi_dsi_host_config_s *config,
1456	  FAR struct mipi_dsi_host **host)
1457	{
1458	  FAR struct esp_mipi_dsi_s *priv = &g_esp_mipi_dsi;
1459	  mipi_dsi_hal_config_t hal_config;
1460	  uint32_t phy_ref_clock_hz;
1461	  uint32_t timeout_ms;
1462	  int ret;
1463	
1464	  if (config == NULL || host == NULL || config->bus != ESP_MIPI_DSI_BUS0 ||
1465	      config->lane_num == 0 ||
1466	      config->lane_num > ESP_MIPI_DSI_MAX_DATA_LANES ||
1467	      config->lane_bit_rate_mbps < ESP_MIPI_DSI_MIN_RATE_MBPS ||
1468	      config->lane_bit_rate_mbps > ESP_MIPI_DSI_MAX_RATE_MBPS ||
1469	      config->phy_ref_clock_hz < ESP_MIPI_DSI_MIN_PHY_REF_HZ ||
1470	      config->phy_ref_clock_hz > ESP_MIPI_DSI_MAX_PHY_REF_HZ ||
1471	      config->phy_ldo.voltage_mv != ESP_MIPI_DSI_DPHY_VOLTAGE_MV)
1472	    {
1473	      return -EINVAL;
1474	    }
1475	
1476	  ret = nxmutex_lock(&priv->lock);
1477	  if (ret < 0)
1478	    {
1479	      return ret;
1480	    }
1481	
1482	  if (priv->ready)
1483	    {
1484	      *host = &priv->host;
1485	      nxmutex_unlock(&priv->lock);
1486	      return OK;
1487	    }
1488	
1489	  ret = esp_ldo_acquire(&config->phy_ldo, &priv->phy_ldo);
1490	  if (ret < 0)
1491	    {
1492	      syslog(LOG_ERR,
1493	             "ERROR: MIPI-DSI D-PHY LDO acquire failed channel=%u"
1494	             " voltage_mv=%d ret=%d\n",
1495	             config->phy_ldo.channel_id, config->phy_ldo.voltage_mv, ret);
1496	      nxmutex_unlock(&priv->lock);
1497	      return ret;
1498	    }
1499	
1500	  syslog(LOG_INFO,
1501	         "INFO: MIPI-DSI D-PHY LDO ready channel=%u voltage_mv=%d"
1502	         " lanes=%u rate_mbps=%" PRIu32 " ref_hz=%" PRIu32 "\n",
1503	         config->phy_ldo.channel_id, config->phy_ldo.voltage_mv,
1504	         config->lane_num, config->lane_bit_rate_mbps,
1505	         config->phy_ref_clock_hz);
1506	
1507	  timeout_ms = config->timeout_ms == 0 ? ESP_MIPI_DSI_DEFAULT_TIMEOUT_MS :
1508	                                         config->timeout_ms;
1509	  priv->timeout_ticks = MSEC2TICK(timeout_ms);
1510	  if (priv->timeout_ticks == 0)
1511	    {
1512	      priv->timeout_ticks = 1;
1513	    }
1514	
1515	  esp_mipi_dsi_enable_clocks(config->bus, true);
1516	  syslog(LOG_INFO, "INFO: MIPI-DSI clocks enabled bus=%u\n", config->bus);
1517	
1518	  ret = esp_mipi_dsi_enable_phy_clock_sources(priv, config->bus,
1519	                                               &phy_ref_clock_hz);
1520	  if (ret < 0)
1521	    {
1522	      syslog(LOG_ERR, "ERROR: MIPI-DSI PHY clock setup ret=%d\n", ret);
1523	      esp_mipi_dsi_enable_clocks(config->bus, false);
1524	      esp_ldo_release(priv->phy_ldo);
1525	      priv->phy_ldo = NULL;
1526	      nxmutex_unlock(&priv->lock);
1527	      return ret;
1528	    }
1529	
1530	  if (phy_ref_clock_hz != config->phy_ref_clock_hz)
1531	    {
1532	      syslog(LOG_WARNING,
1533	             "WARNING: MIPI-DSI configured ref_hz=%" PRIu32
1534	             " differs from active ref_hz=%" PRIu32 "\n",
1535	             config->phy_ref_clock_hz, phy_ref_clock_hz);
1536	    }
1537	
1538	  memset(&hal_config, 0, sizeof(hal_config));
1539	  hal_config.bus_id = config->bus;
1540	  hal_config.lane_bit_rate_mbps = config->lane_bit_rate_mbps;
1541	  hal_config.num_data_lanes = config->lane_num;
1542	  mipi_dsi_hal_init(&priv->hal, &hal_config);
1543	  mipi_dsi_hal_configure_phy_pll(&priv->hal, phy_ref_clock_hz,
1544	                                 config->lane_bit_rate_mbps);
1545	
1546	  syslog(LOG_INFO,
1547	         "INFO: MIPI-DSI PHY PLL configured timeout_ms=%" PRIu32 "\n",
1548	         timeout_ms);
1549	
1550	  ret = esp_mipi_dsi_wait_pll(priv);
1551	  if (ret < 0)
1552	    {
1553	      mipi_dsi_hal_deinit(&priv->hal);
1554	      esp_mipi_dsi_disable_phy_clock_sources(priv, config->bus);
1555	      esp_mipi_dsi_enable_clocks(config->bus, false);
1556	      esp_ldo_release(priv->phy_ldo);
1557	      priv->phy_ldo = NULL;
1558	      nxmutex_unlock(&priv->lock);
1559	      return ret;
1560	    }
1561	
1562	  ret = esp_mipi_dsi_wait_lanes_stopped(priv, config->lane_num);
1563	  if (ret < 0)
1564	    {
1565	      mipi_dsi_hal_deinit(&priv->hal);
1566	      esp_mipi_dsi_disable_phy_clock_sources(priv, config->bus);
1567	      esp_mipi_dsi_enable_clocks(config->bus, false);
1568	      esp_ldo_release(priv->phy_ldo);
1569	      priv->phy_ldo = NULL;
1570	      nxmutex_unlock(&priv->lock);
1571	      return ret;
1572	    }
1573	
1574	  esp_mipi_dsi_configure_command_mode(priv, config->lane_bit_rate_mbps);
1575	  priv->ready = true;
1576	
1577	  syslog(LOG_INFO, "INFO: MIPI-DSI Host ready bus=%u\n", config->bus);
1578	
1579	  if (!priv->registered)
1580	    {
1581	      ret = mipi_dsi_host_register(&priv->host);
1582	      if (ret < 0)
1583	        {
1584	          priv->ready = false;
1585	          mipi_dsi_hal_deinit(&priv->hal);
1586	          esp_mipi_dsi_disable_phy_clock_sources(priv, config->bus);
1587	          esp_mipi_dsi_enable_clocks(config->bus, false);
1588	          esp_ldo_release(priv->phy_ldo);
1589	          priv->phy_ldo = NULL;
1590	          nxmutex_unlock(&priv->lock);
1591	          return ret;
1592	        }
1593	
1594	      priv->registered = true;
1595	    }
1596	
1597	  *host = &priv->host;
1598	  nxmutex_unlock(&priv->lock);
1599	  return OK;
1600	}
