1602	int esp_mipi_dsi_host_shutdown(FAR struct mipi_dsi_host *host)
1603	{
1604	  FAR struct esp_mipi_dsi_s *priv = &g_esp_mipi_dsi;
1605	  int ret;
1606	
1607	  if (host != &priv->host)
1608	    {
1609	      return -EINVAL;
1610	    }
1611	
1612	  ret = nxmutex_lock(&priv->lock);
1613	  if (ret < 0)
1614	    {
1615	      return ret;
1616	    }
1617	
1618	  if (!priv->ready)
1619	    {
1620	      nxmutex_unlock(&priv->lock);
1621	      return OK;
1622	    }
1623	
1624	#ifdef CONFIG_ESPRESSIF_MIPI_DSI_VIDEO
1625	  esp_mipi_dsi_video_stop_locked(priv);
1626	#endif
1627	  mipi_dsi_hal_deinit(&priv->hal);
1628	  esp_mipi_dsi_disable_phy_clock_sources(priv, ESP_MIPI_DSI_BUS0);
1629	  esp_mipi_dsi_enable_clocks(ESP_MIPI_DSI_BUS0, false);
1630	  priv->ready = false;
1631	  ret = esp_ldo_release(priv->phy_ldo);
1632	  priv->phy_ldo = NULL;
1633	  nxmutex_unlock(&priv->lock);
1634	  return ret;
1635	}
