1637	/****************************************************************************
1638	 * Name: esp_mipi_dsi_video_pattern_start
1639	 ****************************************************************************/
1640	
1641	int esp_mipi_dsi_video_pattern_start(
1642	  FAR struct mipi_dsi_host *host,
1643	  FAR const struct esp_mipi_dsi_video_pattern_config_s *config)
1644	{
1645	#ifdef CONFIG_ESPRESSIF_MIPI_DSI_VIDEO
1646	  FAR struct esp_mipi_dsi_s *priv = &g_esp_mipi_dsi;
1647	  mipi_dsi_pattern_type_t pattern;
1648	  int ret;
1649	
1650	  if (host != &priv->host || config == NULL ||
1651	      !esp_mipi_dsi_video_timing_valid(config->channel, config->hactive,
1652	                                        config->vactive,
1653	                                        config->pixel_clock_hz))
1654	    {
1655	      return -EINVAL;
1656	    }
1657	
1658	  ret = esp_mipi_dsi_video_pattern_type(config->pattern, &pattern);
1659	  if (ret < 0)
1660	    {
1661	      return ret;
1662	    }
1663	
1664	  ret = nxmutex_lock(&priv->lock);
1665	  if (ret < 0)
1666	    {
1667	      return ret;
1668	    }
1669	
1670	  if (!priv->ready)
1671	    {
1672	      ret = -ESHUTDOWN;
1673	    }
1674	  else if (priv->video_running)

1675	    {
1676	      ret = -EALREADY;
1677	    }
1678	  else
1679	    {
1680	      ret = esp_mipi_dsi_enable_dpi_clock(priv, config->pixel_clock_hz);
1681	      if (ret == OK)
1682	        {
1683	          /* The bridge owns the DPI timing registers.  Its register clock
1684	           * must be running before those registers are programmed.
1685	           */
1686	
1687	          mipi_dsi_brg_ll_force_enable_reg_clock(priv->hal.bridge, true);
1688	          mipi_dsi_brg_ll_enable_ref_clock(priv->hal.bridge, true);
1689	
1690	          esp_mipi_dsi_video_configure_host(
1691	            priv, config->channel, config->hactive, config->hsync,
1692	            config->hback_porch, config->hfront_porch, config->vactive,
1693	            config->vsync, config->vback_porch, config->vfront_porch,
1694	            config->hsync_active_low, config->vsync_active_low,
1695	            LCD_COLOR_FMT_RGB888);
1696	          mipi_dsi_host_ll_dpi_set_pattern_type(priv->hal.host, pattern);
1697	
1698	          /* Keep the same bridge-side format and timing contract as the
1699	           * ESP-IDF DPI panel path.  M2a intentionally selects the bridge
1700	           * flow controller because its Host video pattern generator has no
1701	           * framebuffer or GDMA producer.
1702	           */
1703	
1704	          esp_mipi_dsi_video_configure_bridge(
1705	            priv, config->hactive, config->vactive,
1706	            24, LCD_COLOR_FMT_RGB888, LCD_COLOR_FMT_RGB888,
1707	            MIPI_DSI_LL_FLOW_CONTROLLER_BRIDGE);
1708	          mipi_dsi_brg_ll_enable_dpi_output(priv->hal.bridge, false);
1709	          mipi_dsi_brg_ll_enable(priv->hal.bridge, true);
1710	          mipi_dsi_brg_ll_update_dpi_config(priv->hal.bridge);
1711	          mipi_dsi_host_ll_enable_bta(priv->hal.host, false);
1712	          mipi_dsi_host_ll_set_clock_lane_state(
1713	            priv->hal.host, MIPI_DSI_LL_CLOCK_LANE_STATE_AUTO);
1714	          mipi_dsi_host_ll_enable_video_mode(priv->hal.host, true);
1715	          mipi_dsi_brg_ll_enable_dpi_output(priv->hal.bridge, true);
1716	          mipi_dsi_brg_ll_update_dpi_config(priv->hal.bridge);
1717	          priv->video_running = true;
1718	          esp_mipi_dsi_dump_video_state(priv, "started");
1719	          syslog(LOG_INFO,
1720	                 "INFO: MIPI-DSI DPI pattern Host started channel=%u "
1721	                 "size=%ux%u pixel_clock_hz=%" PRIu32 " pattern=%d; "
1722	                 "visual verification pending\n",
1723	                 config->channel, config->hactive, config->vactive,
1724	                 config->pixel_clock_hz, config->pattern);
1725	        }
1726	    }
1727	
1728	  nxmutex_unlock(&priv->lock);
1729	  return ret;
1730	#else
1731	  (void)host;
1732	  (void)config;
1733	  return -ENOTSUP;
1734	#endif
1735	}
