1908	/****************************************************************************
1909	 * Name: esp_mipi_dsi_dma_buffer_allocate
1910	 ****************************************************************************/
1911	
1912	int esp_mipi_dsi_dma_buffer_allocate(size_t bytes, FAR void **buffer)
1913	{
1914	#ifdef CONFIG_ESPRESSIF_MIPI_DSI_VIDEO_DMA
1915	  if (buffer == NULL || bytes == 0)
1916	    {
1917	      return -EINVAL;
1918	    }
1919	
1920	  /* The ESP HAL heap_caps compatibility layer maps non-retention requests
1921	   * to kmm_memalign().  On this board CONFIG_MM_KERNEL_HEAP reserves that
1922	   * heap for internal SRAM, while CONFIG_ESPRESSIF_SPIRAM_USER_HEAP makes
1923	   * the standard NuttX user heap the PSRAM heap.  Allocate through memalign
1924	   * deliberately instead of asking heap_caps for MALLOC_CAP_SPIRAM, so the
1925	   * 1024x600 RGB888 scanout buffer is not constrained by the small internal
1926	   * kernel heap.
1927	   */
1928	
1929	  *buffer = memalign(ESP_MIPI_DSI_DMA_BUFFER_ALIGNMENT, bytes);
1930	  if (*buffer == NULL)
1931	    {
1932	      syslog(LOG_ERR,
1933	             "ERROR: MIPI-DSI DMA PSRAM allocation failed bytes=%zu\n",
1934	             bytes);
1935	      return -ENOMEM;
1936	    }
1937	
1938	  memset(*buffer, 0, bytes);
1939	  syslog(LOG_INFO,
1940	         "INFO: MIPI-DSI DMA PSRAM buffer allocated bytes=%zu alignment=%u\n",
1941	         bytes, ESP_MIPI_DSI_DMA_BUFFER_ALIGNMENT);
1942	  return OK;
1943	#else
1944	  (void)bytes;
1945	  (void)buffer;
1946	  return -ENOTSUP;
1947	#endif
1948	}
