1951	 * Name: esp_mipi_dsi_dma_buffer_sync_for_device
1952	 ****************************************************************************/
1953	
1954	int esp_mipi_dsi_dma_buffer_sync_for_device(FAR void *buffer, size_t bytes)
1955	{
1956	#ifdef CONFIG_ESPRESSIF_MIPI_DSI_VIDEO_DMA
1957	  esp_err_t result;
