516	static void esp_mipi_dsi_configure_command_mode(
517	  FAR struct esp_mipi_dsi_s *priv, uint32_t lane_bit_rate_mbps)
518	{
519	  FAR dsi_host_dev_t *host = priv->hal.host;
520	  uint32_t lane_byte_clock_mhz = lane_bit_rate_mbps / 8;
521	  uint32_t escape_clock_div;
522	
523	  escape_clock_div =
524	    (lane_byte_clock_mhz + ESP_MIPI_DSI_ESCAPE_CLOCK_MHZ - 1) /
525	    ESP_MIPI_DSI_ESCAPE_CLOCK_MHZ;
526	  if (escape_clock_div < 2)
527	    {
528	      escape_clock_div = 2;
529	    }
530	
531	  mipi_dsi_host_ll_enable_video_mode(host, false);
532	  mipi_dsi_host_ll_set_clock_lane_state(
533	    host, MIPI_DSI_LL_CLOCK_LANE_STATE_AUTO);
534	  mipi_dsi_phy_ll_set_switch_time(host, 50, 104, 46, 128);
535	  mipi_dsi_host_ll_enable_rx_crc(host, true);
536	  mipi_dsi_host_ll_enable_rx_ecc(host, true);
537	  mipi_dsi_host_ll_enable_tx_eotp(host, true, false);
538	  mipi_dsi_host_ll_enable_rx_eotp(host, true);
539	  mipi_dsi_host_ll_set_timeout_clock_division(
540	    host, (lane_byte_clock_mhz + ESP_MIPI_DSI_TIMEOUT_CLOCK_MHZ - 1) /
541	    ESP_MIPI_DSI_TIMEOUT_CLOCK_MHZ);
542	  mipi_dsi_host_ll_set_escape_clock_division(host, escape_clock_div);
543	  mipi_dsi_host_ll_set_timeout_count(host, 0, 0, 0, 0, 0, 0, 0);
544	  mipi_dsi_phy_ll_set_max_read_time(host, ESP_MIPI_DSI_MAX_READ_TIME);
545	  mipi_dsi_phy_ll_set_stop_wait_time(host, ESP_MIPI_DSI_STOP_WAIT_TIME);
546	}
