644	  mipi_dsi_host_ll_dpi_enable_lp_command(priv->hal.host, true);
645	  mipi_dsi_host_ll_dpi_set_video_burst_type(
646	    priv->hal.host, MIPI_DSI_LL_VIDEO_BURST_WITH_SYNC_PULSES);
647	  mipi_dsi_host_ll_dpi_set_null_packet_size(priv->hal.host, 0);
648	  mipi_dsi_host_ll_dpi_set_trunks_num(priv->hal.host, 0);
649	  mipi_dsi_host_ll_dpi_set_video_packet_pixel_num(priv->hal.host, hactive);
650	
651	  mipi_dsi_hal_host_dpi_set_horizontal_timing(
652	    &priv->hal, hsync, hback_porch, hactive, hfront_porch);
653	  mipi_dsi_hal_host_dpi_set_vertical_timing(
654	    &priv->hal, vsync, vback_porch, vactive, vfront_porch);
