658	 * Name: esp_mipi_dsi_video_configure_bridge
659	 ****************************************************************************/
660	
661	static void esp_mipi_dsi_video_configure_bridge(
662	  FAR struct esp_mipi_dsi_s *priv, uint16_t hactive, uint16_t vactive,
