681	 *
682	 * Description:
683	 *   Report the first Bridge underrun outside interrupt context.  The ISR
684	 *   records only register snapshots and queues this worker so logging never
685	 *   delays DSI or GDMA interrupt delivery.
686	 ****************************************************************************/
687	
688	static void esp_mipi_dsi_bridge_underrun_worker(FAR void *arg)
689	{
690	  FAR struct esp_mipi_dsi_s *priv = arg;
691	  irqstate_t flags;
692	  uint32_t count;
693	  uint32_t raw;
694	  uint32_t status;
695	  uint32_t frame;
696	
697	  if (priv == NULL)
698	    {
699	      return;
700	    }
701	
702	  flags = spin_lock_irqsave(&priv->bridge_irq_lock);
703	  if (!priv->bridge_underrun_report_pending)
704	    {
705	      spin_unlock_irqrestore(&priv->bridge_irq_lock, flags);
706	      return;
707	    }
708	
709	  priv->bridge_underrun_report_pending = false;
710	  count = priv->bridge_underrun_count;
711	  raw = priv->bridge_first_underrun_raw;
712	  status = priv->bridge_first_underrun_status;
713	  frame = priv->bridge_first_underrun_frame;
714	  spin_unlock_irqrestore(&priv->bridge_irq_lock, flags);
715	
716	  syslog(LOG_ERR,
717	         "ERROR: MIPI-DSI Bridge first underrun count=%" PRIu32
718	         " raw=%08" PRIx32 " status=%08" PRIx32
719	         " dma_frames=%" PRIu32 "\n",
720	         count, raw, status, frame);
721	}
