723	/****************************************************************************
724	 * Name: esp_mipi_dsi_bridge_interrupt
725	 *
726	 * Description:
727	 *   Latch and clear Bridge underrun only.  A DSI Bridge interrupt can occur
728	 *   while GDMA is serving the next frame, so this handler must not take the
729	 *   video mutex, allocate memory, or print directly.
730	 ****************************************************************************/
731	
732	static int esp_mipi_dsi_bridge_interrupt(int irq, FAR void *context,
733	                                         FAR void *arg)
734	{
735	  FAR struct esp_mipi_dsi_s *priv = arg;
736	  FAR dsi_brg_dev_t *bridge;
737	  irqstate_t flags;
738	  uint32_t status;
739	  uint32_t raw;
740	  bool queue_report = false;
741	
742	  (void)irq;
743	  (void)context;
744	
745	  if (priv == NULL || priv->hal.bridge == NULL)
746	    {
747	      return OK;
748	    }
749	
750	  bridge = priv->hal.bridge;
751	  status = mipi_dsi_brg_ll_get_interrupt_status(bridge);
752	  if ((status & MIPI_DSI_BRG_LL_EVENT_UNDERRUN) == 0)
753	    {
754	      return OK;
755	    }
756	
757	  raw = bridge->int_raw.val;
758	  mipi_dsi_brg_ll_clear_interrupt_status(
759	    bridge, MIPI_DSI_BRG_LL_EVENT_UNDERRUN);
760	
761	  flags = spin_lock_irqsave(&priv->bridge_irq_lock);
762	  priv->bridge_underrun_count++;
763	  if (!priv->bridge_first_underrun_seen)
764	    {
765	      priv->bridge_first_underrun_seen = true;
766	      priv->bridge_first_underrun_raw = raw;
767	      priv->bridge_first_underrun_status = status;
768	      priv->bridge_first_underrun_frame = priv->dma_frame_count;
769	      priv->bridge_underrun_report_pending = true;
770	      queue_report = true;
771	    }
772	
773	  spin_unlock_irqrestore(&priv->bridge_irq_lock, flags);
774	
775	  if (queue_report)
776	    {
777	      work_queue(LPWORK, &priv->bridge_underrun_work,
778	                 esp_mipi_dsi_bridge_underrun_worker, priv, 0);
779	    }
780	
781	  return OK;
782	}
