42	            frame[y * LCD_WIDTH + x] = bars[bar];
43	        }
44	    }
45	
46	    /* The lower area verifies gray levels, sharp transitions, and all primaries. */
47	    for (int y = bar_area_height; y < LCD_HEIGHT; ++y) {
48	        for (int x = 0; x < LCD_WIDTH; ++x) {
49	            uint8_t level = (uint8_t)((uint32_t)x * 255U / (LCD_WIDTH - 1));
50	            frame[y * LCD_WIDTH + x] = RGB565(level, level, level);
51	        }
52	    }
53	
54	    /* A checker strip makes scaling or pixel errors obvious. */
55	    const int checker_top = LCD_HEIGHT - 32;
56	    for (int y = checker_top; y < LCD_HEIGHT; ++y) {
57	        for (int x = 0; x < LCD_WIDTH; ++x) {
58	            bool white = ((x / 8) + ((y - checker_top) / 8)) & 1;
59	            frame[y * LCD_WIDTH + x] = white ? RGB565(255, 255, 255) : RGB565(0, 0, 0);
60	        }
61	    }
62	}
