213	    dpi_panel, &frame_buffer, &frame_buffer_bytes);
214	  if (ret < 0)
215	    {
216	      return ret;
217	    }
218	
219	  /* The known-good ESP-IDF sample enables brightness before its first
220	   * draw_bitmap().  Preserve that order for this one-to-one P4X experiment.
221	   */
222	
223	  ret = board_mipi_dsi_backlight_set(true);
224	  if (ret < 0)
225	    {
226	      return ret;
227	    }
228	
229	  dsi_probe_fill_rgb565_colour_bars(frame_buffer,
230	                                    dpi_panel->config.hactive,
231	                                    dpi_panel->config.vactive);
232	
233	  ret = ek79007_panel_draw_bitmap(panel, frame_buffer, frame_buffer_bytes);
234	  if (ret < 0)
235	    {
236	      board_mipi_dsi_backlight_set(false);
237	      return ret;
238	    }
239	
240	  printf("dsi_probe: EK79007 DPI RGB565 vertical colour bars active for "
241	         "%u seconds; "
242	         "LVGL is not involved\n", seconds);
243	  printf("dsi_probe: draw_bitmap() submitted; visually confirm colour bars "
244	         "before recording a display PASS\n");
245	  status_ret = board_mipi_dsi_video_dump_status(host, "probe-start");
246	  if (status_ret < 0)
247	    {
248	      printf("dsi_probe: DMA status snapshot unavailable ret=%d\n",
249	             status_ret);
250	    }
251	
252	  status_ret = board_mipi_dsi_video_sample_phy_status(
253	    host, "probe-start", DSI_PROBE_PHY_SAMPLE_COUNT,
254	    DSI_PROBE_PHY_SAMPLE_INTERVAL_US);
255	  if (status_ret < 0)
256	    {
257	      printf("dsi_probe: PHY activity sample unavailable ret=%d\n",
258	             status_ret);
259	    }
260	
261	  for (elapsed = 0; elapsed < seconds; elapsed++)
262	    {
263	      ret = nxsig_usleep(1000 * 1000);
264	      if (ret < 0)
265	        {
266	          break;
267	        }
268	
269	      if (elapsed == 0)
270	        {
271	          status_ret = board_mipi_dsi_video_dump_status(host,
272	                                                         "probe-after-1s");
273	          if (status_ret < 0)
274	            {
275	              printf("dsi_probe: DMA status snapshot unavailable ret=%d\n",
276	                     status_ret);
277	            }
278	
279	          status_ret = board_mipi_dsi_video_sample_phy_status(
280	            host, "probe-after-1s", DSI_PROBE_PHY_SAMPLE_COUNT,
281	            DSI_PROBE_PHY_SAMPLE_INTERVAL_US);
282	          if (status_ret < 0)
283	            {
284	              printf("dsi_probe: PHY activity sample unavailable ret=%d\n",
285	                     status_ret);
286	            }
287	        }
288	    }
289	
290	  status_ret = board_mipi_dsi_video_dump_status(host, "probe-before-stop");
291	  if (status_ret < 0)
292	    {
293	      printf("dsi_probe: DMA status snapshot unavailable ret=%d\n",
294	             status_ret);
295	    }
296	
297	  display_ret = dsi_probe_panel_shutdown(panel);
298	  if (display_ret < 0 && ret == OK)
299	    {
300	      ret = display_ret;
301	    }
302	
303	  return ret;
304	}
