194	/****************************************************************************
195	 * Name: board_mipi_dsi_fill_colour_bars
196	 ****************************************************************************/
197	
198	static void board_mipi_dsi_fill_colour_bars(FAR uint8_t *frame_buffer)
199	{
200	  static const uint8_t colours[BOARD_MIPI_DSI_COLOUR_BAR_COUNT][3] =
201	  {
202	    {0xff, 0xff, 0xff}, /* White */
203	    {0xff, 0xff, 0x00}, /* Yellow */
204	    {0x00, 0xff, 0xff}, /* Cyan */
205	    {0x00, 0xff, 0x00}, /* Green */
206	    {0xff, 0x00, 0xff}, /* Magenta */
207	    {0xff, 0x00, 0x00}, /* Red */
208	    {0x00, 0x00, 0xff}, /* Blue */
209	    {0x00, 0x00, 0x00}, /* Black */
210	  };
211	
212	  FAR uint8_t *pixel = frame_buffer;
213	  uint32_t x;
214	  uint32_t y;
215	  uint32_t bar;
216	
217	  for (y = 0; y < BOARD_MIPI_DSI_VACTIVE; y++)
218	    {
219	      for (x = 0; x < BOARD_MIPI_DSI_HACTIVE; x++)
220	        {
221	          bar = x * BOARD_MIPI_DSI_COLOUR_BAR_COUNT /
222	                BOARD_MIPI_DSI_HACTIVE;
223	          pixel[0] = colours[bar][0];
224	          pixel[1] = colours[bar][1];
225	          pixel[2] = colours[bar][2];
226	          pixel += BOARD_MIPI_DSI_BYTES_PER_PIXEL;
227	        }
228	    }
229	}
