231	/****************************************************************************
232	 * Name: board_mipi_dsi_allocate_frame_buffer
233	 ****************************************************************************/
234	
235	static int board_mipi_dsi_allocate_frame_buffer(void)
236	{
237	  FAR void *frame_buffer;
238	  int ret;
239	
240	  if (g_board_mipi_dsi_frame_buffer != NULL)
241	    {
242	      return OK;
243	    }
244	
245	  /* ESP HAL heap/cache APIs are deliberately contained by the P4 chip
246	   * adapter.  The board owns the pixel data and lifetime only.
247	   */
248	
249	  ret = esp_mipi_dsi_dma_buffer_allocate(BOARD_MIPI_DSI_FRAME_BYTES,
250	                                         &frame_buffer);
251	  if (ret < 0)
252	    {
253	      syslog(LOG_ERR,
254	             "ERROR: P4X DSI DMA frame allocation bytes=%zu ret=%d\n",
255	             BOARD_MIPI_DSI_FRAME_BYTES, ret);
256	      return ret;
257	    }
258	
259	  g_board_mipi_dsi_frame_buffer = frame_buffer;
260	  board_mipi_dsi_fill_colour_bars(g_board_mipi_dsi_frame_buffer);
261	  ret = esp_mipi_dsi_dma_buffer_sync_for_device(
262	    g_board_mipi_dsi_frame_buffer, BOARD_MIPI_DSI_FRAME_BYTES);
263	  if (ret < 0)
264	    {
265	      syslog(LOG_ERR, "ERROR: P4X DSI DMA frame cache sync ret=%d\n", ret);
266	      esp_mipi_dsi_dma_buffer_free(g_board_mipi_dsi_frame_buffer);
267	      g_board_mipi_dsi_frame_buffer = NULL;
268	      return ret;
269	    }
270	
