static void board_mipi_dsi_release_frame_buffer(void)
{
  if (g_board_mipi_dsi_frame_buffer != NULL)
    {
      esp_mipi_dsi_dma_buffer_free(g_board_mipi_dsi_frame_buffer);
      g_board_mipi_dsi_frame_buffer = NULL;
