714	
715	int gt911_register(FAR const char *devpath,
716	                   FAR struct i2c_master_s *i2c,
717	                   FAR const struct gt911_config_s *config)
718	{
719	  FAR struct gt911_dev_s *priv;
720	  FAR const struct gt911_board_s *board;
721	  uint8_t max_points;
722	  uint8_t event_buffer_count;
723	  int ret;
724	
725	  if (devpath == NULL || i2c == NULL || config == NULL)
726	    {
727	      return -EINVAL;
728	    }
729	
730	  board = config->board;
731	  if ((board == NULL || board->irq_attach == NULL ||
732	       board->irq_enable == NULL) && config->poll_interval_ms == 0)
733	    {
734	      return -EINVAL;
735	    }
736	
737	  max_points = config->max_points == 0 ? GT911_MAX_POINTS :
738	                                         config->max_points;
739	  if (max_points > GT911_MAX_POINTS)
740	    {
741	      return -EINVAL;
742	    }
743	
744	  event_buffer_count = config->event_buffer_count == 0 ?
745	                       GT911_EVENT_BUFFER_COUNT : config->event_buffer_count;
746	  priv = kmm_zalloc(sizeof(*priv) + SIZEOF_TOUCH_SAMPLE_S(max_points));
747	  if (priv == NULL)
748	    {
749	      return -ENOMEM;
750	    }
751	
752	  priv->i2c = i2c;
753	  priv->config = config;
754	  priv->board = board;
755	  priv->frequency = config->frequency == 0 ? GT911_I2C_FREQUENCY :
756	                                             config->frequency;
757	  priv->address = config->address == 0 ? GT911_I2C_ADDRESS : config->address;
758	  priv->poll_interval_ms = config->poll_interval_ms;
759	  priv->max_points = max_points;
760	  priv->polling = config->poll_interval_ms != 0;
761	  priv->lower.maxpoint = max_points;
762	  nxmutex_init(&priv->lock);
763	
764	  if (board != NULL && board->reset != NULL)
765	    {
766	      ret = board->reset(board);
767	      if (ret < 0)
768	        {
769	          goto err_destroy_lock;
770	        }
771	    }
772	
773	  ret = gt911_probe(priv);
774	  if (ret < 0)
775	    {
776	      goto err_destroy_lock;
777	    }
778	
779	  ret = touch_register(&priv->lower, devpath, event_buffer_count);
780	  if (ret < 0)
781	    {
782	      goto err_destroy_lock;
783	    }
784	
785	  if (priv->polling)
786	    {
787	      ret = gt911_schedule_poll(priv);
788	      if (ret < 0)
789	        {
790	          goto err_unregister_touch;
791	        }
792	
793	#ifdef CONFIG_INPUT_GT911_DIAGNOSTICS
794	      printf("gt911: diagnostics enabled poll_ms=%u address=0x%02x\n",
795	             priv->poll_interval_ms, priv->address);
796	#endif
797	      return OK;
798	    }
799	
800	  ret = board->irq_attach(board, gt911_interrupt, priv);
801	  if (ret < 0)
802	    {
803	      goto err_unregister_touch;
804	    }
805	
806	  board->irq_enable(board, true);
807	  return OK;
808	
809	err_unregister_touch:
810	  touch_unregister(&priv->lower, devpath);
811	err_destroy_lock:
812	  nxmutex_destroy(&priv->lock);
813	  kmm_free(priv);
814	  return ret;
815	}
