75	/****************************************************************************
76	 * Name: setup_smartfs
77	 *
78	 * Description:
79	 *   Provide a block driver wrapper around MTD partition and mount a
80	 *   SMART FS over it.
81	 *
82	 * Parameters:
83	 *   smartn - Number used to register the mtd partition: /dev/smartx, where
84	 *            x = smartn.
85	 *   mtd    - Pointer to a pre-allocated mtd partition.
86	 *   mnt_pt - Mount point
87	 *
88	 * Returned Value:
89	 *   Zero on success; a negated errno value on failure.
90	 *
91	 ****************************************************************************/
92	
93	#if defined (CONFIG_ESPRESSIF_SPIFLASH_SMARTFS)
94	static int setup_smartfs(int smartn, struct mtd_dev_s *mtd,
95	                         const char *mnt_pt)
96	{
97	  int ret = OK;
98	  char path[22];
99	
100	  ret = smart_initialize(smartn, mtd, NULL);
101	  if (ret < 0)
102	    {
103	      syslog(LOG_INFO, "smart_initialize failed, "
104	             "Trying to erase first...\n");
105	      ret = mtd->ioctl(mtd, MTDIOC_BULKERASE, 0);
106	      if (ret < 0)
107	        {
108	          syslog(LOG_ERR, "ERROR: ioctl(BULKERASE) failed: %d\n", ret);
109	          return ret;
110	        }
111	
112	      syslog(LOG_INFO, "Erase successful, initializing it again.\n");
113	      ret = smart_initialize(smartn, mtd, NULL);
114	      if (ret < 0)
115	        {
116	          syslog(LOG_ERR, "ERROR: smart_initialize failed: %d\n", ret);
117	          return ret;
118	        }
119	    }
120	
121	  if (mnt_pt != NULL)
122	    {
123	      snprintf(path, sizeof(path), "/dev/smart%d", smartn);
124	
125	      ret = nx_mount(path, mnt_pt, "smartfs", 0, NULL);
126	      if (ret < 0)
127	        {
128	          syslog(LOG_ERR, "ERROR: Failed to mount the FS volume: %d\n", ret);
129	          if (ret == -ENODEV)
130	            {
131	              syslog(LOG_WARNING, "Smartfs seems unformatted. "
132	                     "Did you run 'mksmartfs /dev/smart%d'?\n", smartn);
133	            }
134	
135	          return ret;
136	        }
137	    }
138	
139	  return ret;
140	}
141	#endif
