143	/****************************************************************************
144	 * Name: setup_littlefs
145	 *
146	 * Description:
147	 *   Register a mtd driver and mount a Little FS over it.
148	 *
149	 * Parameters:
150	 *   path   - Path name used to register the mtd driver.
151	 *   mtd    - Pointer to a pre-allocated mtd partition.
152	 *   mnt_pt - Mount point
153	 *   priv   - Privileges
154	 *
155	 * Returned Value:
156	 *   Zero on success; a negated errno value on failure.
157	 *
158	 ****************************************************************************/
159	
160	#if defined (CONFIG_ESPRESSIF_SPIFLASH_LITTLEFS)
161	static int setup_littlefs(const char *path, struct mtd_dev_s *mtd,
162	                          const char *mnt_pt, int priv)
163	{
164	  int ret = OK;
165	
166	#ifdef CONFIG_ESPRESSIF_STORAGE_MTD_DIAGNOSTICS
167	  syslog(LOG_INFO, "P4X LittleFS register: source=%s mount=%s\n",
168	         path, mnt_pt ? mnt_pt : "(none)");
169	#endif
170	  ret = register_mtddriver(path, mtd, priv, NULL);
171	  if (ret < 0)
172	    {
173	      syslog(LOG_ERR, "ERROR: Failed to register MTD: %d\n", ret);
174	      return ERROR;
175	    }
176	
177	  if (mnt_pt != NULL)
178	    {
179	      ret = nx_mount(path, mnt_pt, "littlefs", 0, NULL);
180	      if (ret < 0)
181	        {
182	#ifdef CONFIG_ESPRESSIF_STORAGE_MTD_DIAGNOSTICS
183	          syslog(LOG_WARNING,
184	                 "P4X LittleFS initial mount failed: ret=%d; "
185	                 "retrying with destructive forceformat\n", ret);
186	#endif
187	          ret = nx_mount(path, mnt_pt, "littlefs", 0, "forceformat");
188	          if (ret < 0)
189	            {
190	              syslog(LOG_ERR, "ERROR: Failed to mount the FS volume: %d\n",
191	                     ret);
192	              return ret;
193	            }
194	        }
195	    }
196	
197	#ifdef CONFIG_ESPRESSIF_STORAGE_MTD_DIAGNOSTICS
198	  syslog(LOG_INFO, "P4X LittleFS mounted: source=%s mount=%s\n",
199	         path, mnt_pt ? mnt_pt : "(none)");
200	#endif
201	
202	  return OK;
203	}
204	#endif
