291	/****************************************************************************
292	 * Name: init_storage_partition
293	 *
294	 * Description:
295	 *   Initialize partition that is dedicated to general use.
296	 *
297	 * Input Parameters:
298	 *   None
299	 *
300	 * Returned Value:
301	 *   Zero on success; a negated errno value on failure.
302	 *
303	 ****************************************************************************/
304	
305	static int init_storage_partition(void)
306	{
307	  int ret = OK;
308	  struct mtd_dev_s *mtd;
309	
310	#ifdef CONFIG_ESPRESSIF_STORAGE_MTD_DIAGNOSTICS
311	  syslog(LOG_INFO,
312	         "P4X storage bring-up: offset=0x%08x size=0x%08x\n",
313	         CONFIG_ESPRESSIF_STORAGE_MTD_OFFSET,
314	         CONFIG_ESPRESSIF_STORAGE_MTD_SIZE);
315	#endif
316	
317	  ret = esp_spiflash_initialize();
318	  if (ret < 0)
319	    {
320	      syslog(LOG_ERR,
321	             "ERROR: Failed to initialize the default SPI Flash chip: %d\n",
322	             ret);
323	      return ret;
324	    }
325	
326	  mtd = esp_spiflash_alloc_mtdpart(CONFIG_ESPRESSIF_STORAGE_MTD_OFFSET,
327	                                   CONFIG_ESPRESSIF_STORAGE_MTD_SIZE);
328	  if (!mtd)
329	    {
330	      syslog(LOG_ERR, "ERROR: Failed to alloc MTD partition of SPI Flash\n");
331	      return ERROR;
332	    }
333	
334	#if defined (CONFIG_ESPRESSIF_SPIFLASH_SMARTFS)
335	
336	  ret = setup_smartfs(0, mtd, CONFIG_ESPRESSIF_SPIFLASH_FS_MOUNT_PT);
337	  if (ret < 0)
338	    {
339	      syslog(LOG_ERR, "ERROR: Failed to setup smartfs\n");
340	      return ret;
341	    }
342	
343	#elif defined (CONFIG_ESPRESSIF_SPIFLASH_NXFFS)
344	
345	  ret = setup_nxffs(mtd, CONFIG_ESPRESSIF_SPIFLASH_FS_MOUNT_PT);
346	  if (ret < 0)
347	    {
348	      syslog(LOG_ERR, "ERROR: Failed to setup nxffs\n");
349	      return ret;
350	    }
351	
352	#elif defined (CONFIG_ESPRESSIF_SPIFLASH_LITTLEFS)
353	
354	  const char *path = "/dev/espflash";
355	  ret = setup_littlefs(path, mtd, CONFIG_ESPRESSIF_SPIFLASH_FS_MOUNT_PT,
356	                       0755);
357	  if (ret < 0)
358	    {
359	      syslog(LOG_ERR, "ERROR: Failed to setup littlefs\n");
360	      return ret;
361	    }
362	
363	#elif defined (CONFIG_ESPRESSIF_SPIFLASH_SPIFFS)
364	
365	  const char *path = "/dev/espflash";
366	  ret = setup_spiffs(path, mtd, CONFIG_ESPRESSIF_SPIFLASH_FS_MOUNT_PT, 0755);
367	  if (ret < 0)
368	    {
369	      syslog(LOG_ERR, "ERROR: Failed to setup spiffs\n");
370	      return ret;
371	    }
372	
373	#elif defined (CONFIG_ESPRESSIF_SPIFLASH_MTD_CONFIG)
374	
375	#  if defined (CONFIG_TESTING_MTD_CONFIG_FAIL_SAFE)
376	
377	  /* To test power-loss resilient kv system,
378	   * we write possible power-loss flash layout into flash
379	   * then start kv system to see if it recovers.
380	   * To do so, we need a mtd driver so that test code can
381	   * write into flash.
382	   */
383	
384	  const char *path = CONFIG_TESTING_MTD_CONFIG_FAIL_SAFE_MOUNTPT_NAME;
385	  ret = register_mtddriver(path, mtd, 0777, NULL);
386	  if (ret < 0)
387	    {
388	      syslog(LOG_ERR, "ERROR: Failed to register MTD: %d\n", ret);
389	      return ret;
390	    }
391	
392	#  else
393	
394	  ret = mtdconfig_register(mtd);
395	  if (ret < 0)
396	    {
397	      syslog(LOG_ERR, "ERROR: Failed to setup mtd config\n");
398	      return ret;
399	    }
400	
401	#  endif
402	
403	#else
404	
405	  ret = register_mtddriver("/dev/espflash", mtd, 0755, NULL);
406	  if (ret < 0)
407	    {
408	      syslog(LOG_ERR, "ERROR: Failed to register MTD: %d\n", ret);
409	      return ret;
410	    }
411	
412	  ret = ftl_initialize(0, mtd);
413	  if (ret < 0)
414	    {
415	      syslog(LOG_ERR, "ERROR: Failed to initialize the FTL layer: %d\n",
416	              ret);
417	      return ret;
418	    }
419	#endif
420	
421	  return ret;
422	}
