514	      syslog(LOG_ERR,
515	             "ERROR: P4X default Flash chip initialization failed: %d\n",
516	             ret);
517	      return -EIO;
518	    }
519	
520	  if (esp_flash_default_chip == NULL ||
521	      !esp_flash_chip_driver_initialized(esp_flash_default_chip))
522	    {
523	      syslog(LOG_ERR,
524	             "ERROR: P4X default Flash chip remains unavailable after "
525	             "initialization\n");
