529	#ifdef CONFIG_ESPRESSIF_STORAGE_MTD_DIAGNOSTICS
530	  syslog(LOG_INFO, "P4X default Flash chip initialized: size=0x%08" PRIx32
531	         "\n", esp_flash_default_chip->size);
532	#endif
533	
534	  return OK;
535	}
